<?php require 'includes/db.php';$ok=false;$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$e=trim($_POST['email']??'');$s=trim($_POST['subject']??'');$m=trim($_POST['message']??'');if($n&&filter_var($e,FILTER_VALIDATE_EMAIL)&&$s&&$m){$q=$pdo->prepare('INSERT INTO contact_messages(name,email,subject,message) VALUES(?,?,?,?)');$q->execute([$n,$e,$s,$m]);$ok=true;}else{$err='Please complete all fields with a valid email.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact Us | ScholarConnect Pro</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'includes/header.php';?><header class="page-header"><span class="eyebrow">GET HELP</span><h1>Contact Us</h1><p>Use the form or official support channels below.</p></header><section class="contact-wrap"><div><div class="contact-card"><span>☎</span><div><h3>MahaDBT Helpline</h3><p>022-49150800</p><small>Official portal support.</small></div></div><div class="contact-card"><span>24</span><div><h3>Chief Minister Helpline</h3><p>1800 120 8040</p><small>Government helpline.</small></div></div><div class="contact-card"><span>🔗</span><div><h3>Official Portal</h3><a class="text-link" target="_blank" href="https://mahadbt.maharashtra.gov.in/">Open MahaDBT →</a></div></div></div><form class="contact-form" method="post"><h2>Send us a message</h2><?php if($ok):?><div class="success">Message saved successfully. Admin can view it in the dashboard.</div><?php elseif($err):?><div class="notice"><?=htmlspecialchars($err)?></div><?php endif;?><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Subject<input name="subject" required></label><label>Message<textarea name="message" rows="6" required></textarea></label><button class="btn btn-primary">Send Message</button></form></section><?php include 'includes/footer.php';?></body></html>
